g = RandomGraph[{50, 120}, DirectedEdges -> True];
{VertexCount[g], EdgeCount[g]}
Max[VertexInDegree[g]]
EdgeCount[g, _ -> 1] (* in-edges of vertex 1 *)

g = RandomGraph[WattsStrogatzGraphDistribution[200, 0.1, 4]];
{MeanClusteringCoefficient[g], MeanGraphDistance[g]} (* small-world signature *)
GraphAssortativity[g]

g = ExampleData[{"NetworkGraph", "ZacharyKarateClub"}];
{hubs, auth} = HITSCentrality[g];
HighlightGraph[g, Pick[VertexList[g], auth, Max[auth]]]
HighlightGraph[g, First[EdgeList[g][[Ordering[EdgeBetweennessCentrality[g], -3]]]]]

g = RandomGraph[{30, 60}];
sim = VertexJaccardSimilarity[g];
(* predict links: highest similarity among non-adjacent pairs *)
candidates = Select[Subsets[VertexList[g], {2}], !EdgeQ[g, UndirectedEdge @@ #] &];
TakeLargestBy[candidates, sim[[#[[1]], #[[2]]]] &, 5]

g = PetersenGraph[];
cols = FindVertexColoring[g];
VertexChromaticNumber[g] (* 3 *)
Graph[g, VertexStyle -> Thread[VertexList[g] -> (ColorData[97] /@ cols)]]
ChromaticPolynomial[CycleGraph[4], x] (* x (x - 1) (x^2 - 3 x + 3) *)

g = RandomGraph[{100, 90}, DirectedEdges -> True];
Length[WeaklyConnectedComponents[g]]
largest = First[ConnectedGraphComponents[UndirectedGraph[g]]]

g = GridGraph[{4, 4}];
levels = <||>;
BreadthFirstScan[g, 1, {"DiscoverVertex" -> ((levels[#1] = #3) &)}];
levels
(* detect a cycle *)
hasCycle = False; DepthFirstScan[g, 1, {"BackEdge" -> (hasCycle = True &)}]; hasCycle

g = GridGraph[{3, 3}];
tour = First[FindPostmanTour[g]];
Length[tour] (* > EdgeCount since some edges repeat *)

g = GridGraph[{3, 3}];
Length[FindPath[g, 1, 9, Infinity, All]] (* 12 simple paths *)
FindEdgeIndependentPaths[g, 1, 9]

g = CycleGraph[5];
EdgeContract[g, 1 <-> 2] (* 4-cycle *)
VertexReplace[g, {1 -> "a", 2 -> "b"}]

dag = DirectedGraph[GridGraph[{3, 3}], "Acyclic"];
TopologicalSort[dag]
IndexGraph[Graph[{"a" <-> "b", "b" <-> "c"}]] (* vertices 1, 2, 3 *)

divides = RelationGraph[Divisible[#2, #1] && #1 != #2 &, Range[12]];
hasse = TransitiveReductionGraph[divides];
LayeredGraphPlot[hasse]

g = GridGraph[{6, 6}];
parts = FindGraphPartition[g, 4];
HighlightGraph[g, Subgraph[g, #] & /@ parts]

